/**
 * Real AI, local everything else: trips are generated by the backend (POST /trips/generate),
 * while auth and saved trips stay in the browser via the mock. Lets the site go live without a database.
 */
import type { GenerateEvent, ItineraryDay, TripRequest } from '../types/trip';
import { mockApi, rememberTrip } from './mock';
import { generateTrip as generateWithAi } from './trips';
import type { Api } from './types';

async function* generateTrip(req: TripRequest, signal?: AbortSignal): AsyncGenerator<GenerateEvent, void, void> {
  const days: ItineraryDay[] = [];
  for await (const ev of generateWithAi(req, signal)) {
    if (ev.type === 'day') days.push(ev.day);
    if (ev.type === 'done') rememberTrip(req, days, ev.trip_id, ev.total_cost_estimate);
    yield ev;
  }
}

export const hybridApi: Api = { ...mockApi, generateTrip };
